      res.writeHead(200, JSON_HEADERS);
      res.end(body);
      return;
    }

    const body = JSON.stringify({ error: 'not found' });
    res.writeHead(404, JSON_HEADERS);
    res.end(body);
  });
}

module.exports = { createServer };"}

